insert into data_features (layer_id, source, source_id, name, kind, geom, props, valid_from, valid_to) values
($q$restricoes_rmsp$q$, $q$limeira$q$, $q$69ef565330725528$q$, $q$Limeira: Perímetro central (PBT > 10 t) — Rua Visconde do Rio Branco$q$, $q$desativada$q$, ST_SetSRID(ST_GeomFromGeoJSON($q${"type":"LineString","coordinates":[[-47.403104,-22.568338],[-47.403747,-22.567718],[-47.404454,-22.567035],[-47.405115,-22.566413],[-47.405879,-22.56571],[-47.4064,-22.565219],[-47.407081,-22.564578],[-47.407749,-22.563948]]}$q$), 4326), $q${"regra_id":"limeira_perimetro_central_10t","municipio":"Limeira","ibge":"3526902","uf":"SP","tipo":"via","regime":"Perímetro central (PBT > 10 t)","nome":"Limeira: vias do perímetro central, veículos com PBT acima de 10 t (carga e descarga) só das 19h às 9h em dias úteis e após as 13h aos sábados","status":"desativada","status_motivo":"Rebaixada na verificação de 2026-10-10: o Dec. 56/2004 confere, mas é regra de horário de carga e descarga, não de circulação. O art. 1º fixa o horário 'para a circulação de veículos com peso bruto total (PBT) acima de 10 toneladas para carga e descarga de mercadorias' nas vias do perímetro central, e o considerando fala em regulamentar o horário dos 'veículos de carga e descarga de mercadorias'. Aplicada como via, barraria o trânsito de passagem, que o ato não proíbe. O formato não tem regra só de destino, então fica registrada para aviso (mesmo tratamento de Vitória, Lei 6.490/2005, e de Poços de Caldas, Lei 5.664/1994).","confianca":"media","janelas":[{"days":[1,2,3,4,5],"from":"09:00","to":"19:00"},{"days":[6],"from":"09:00","to":"13:00"}],"feriados":"aplica","alvo":{"caminhao":true,"qualquer":[{"campo":"pbt_t","acima":10}]},"autorizacao":"Licença especial da Secretaria Municipal de Obras e Transportes, Departamento de Trânsito, afixada no veículo (Decreto 56/2004, art. 3º), para carga e descarga de materiais de construção, concreto, mudanças e outros com veículo acima do limite do art. 1º","excecoes":["Art. 3º: carga e descarga de materiais de construção, concreto, mudanças e outros com licença especial do Departamento de Trânsito"],"base_legal":[{"ato":"Decreto municipal 56, de 26/02/2004 (Limeira)","artigo":"art. 1º (horário das 19h às 9h de segunda a sexta e, aos sábados, após as 13h, para a circulação de veículos com PBT acima de 10 t para carga e descarga nas vias do perímetro central); art. 2º (sinalização); art. 3º (licença especial); art. 4º (vigência na publicação)","url":"https://web1.limeira.sp.gov.br/regulamentacoes/cns_leiDecreto_publico/","nota":"PDF (imagem, 2 folhas) lido no sistema de Leis/Decretos da Prefeitura (busca 'toneladas', tipo Decreto; 'Em Vigor: SIM'); ficha 'Em vigor' também na Legislação Digital da Câmara: https://legislacao.limeira.sp.leg.br/Limeira-SP/DecretosMunicipais/56-2004 (sem arquivo anexado). Cópia em atos/3526902/D56_2004.pdf."}],"nota":"Janela restrita inferida do horário permitido: dias úteis 9h–19h e sábado 9h–13h (a janela permitida de sexta, 19h–9h, cobre a madrugada de sábado; domingo não é citado = livre). O ato fala em 'circulação de veículos com PBT acima de 10 t para carga e descarga' nas vias listadas; não excetua feriados. Confiança média: interpretação do sábado e ato de 2004 sem alteração localizada (consta 'Em vigor' nos dois sistemas oficiais). Verificação de 2026-10-10: o ato só lista as janelas permitidas (19h às 9h de segunda a sexta e, aos sábados, após as 13h). Não diz se a janela de sexta (19h–9h) alcança a manhã de sábado e não menciona o domingo. As janelas registradas (seg–sex 9h–19h e sáb 9h–13h, domingo livre) são uma leitura possível, não a única.","fonte_geometria":"Trechos 'rua X entre Y e Z' do art. 1º (14 segmentos no centro de Limeira).","vigencia_inicio":"2004-02-26","vuc":null,"vuc_nota":"O município não define VUC: os decretos usam eixos/carreta (Anel Viário) e PBT (centro).","inciso":"art. 1º","via":"Rua Visconde do Rio Branco","trecho":"Rua Visconde do Rio Branco, entre Santa Terezinha e Sete de Setembro (Decreto 56/2004, art. 1º; no ato: 'Santa Terezinha' e '7 de Setembro')","aproximado":false,"nota_trecho":"A via tem um só way no OSM (157091268): pontas em lonlat nos cruzamentos do ato, percorridas pelo Valhalla no sentido da mão única.","osm_way_id":null,"nome_osm":"Rua Visconde do Rio Branco","mao_unica":true,"sentido":"unico","comprimento_m":682,"verificado_em":"2026-10-11"}$q$::jsonb, $q$2004-02-26$q$::timestamptz, null::timestamptz),
